  FILTER(LCASE(STR(?riskTol)) = "conservative") .

  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:liquidityScore ?liq .
  FILTER(xsd:decimal(?liq) < 50) .

  ?sa a wm:SectorAllocation ;
      wm:investorId ?investorId ;
      wm:sector ?sector ;
      wm:allocationPct ?alloc .
  FILTER(LCASE(STR(?sector)) = "banking") .
  FILTER(xsd:decimal(?alloc) > 0) .
}"}

{"Q1": "PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wm: <https://wealth.example.org/ontology/>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?rt ;
            wm:hasPortfolioHealth ?ph ;
            wm:hasSectorAllocation ?sa .

  FILTER(?rt = "Conservative")

  ?ph wm:liquidityScore ?liq .
  FILTER(?liq < 50)

  ?sa wm:allocationPct ?alloc ;
      wm:sector ?sector .
  FILTER(?alloc > 0)
  FILTER(?sector = "Corporate")
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTolerance .
  FILTER(LCASE(STR(?riskTolerance)) = "aggressive") .

  ?ph a wm:PortfolioHealth ;
       wm:healthOfInvestor ?inv ;
       wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?divScore) < 25) .

  ?sr a wm:ScenarioRebalancing ;
       wm:scenarioRebalancingOfInvestor ?inv ;
       wm:scenario ?scenario .
  FILTER(LCASE(STR(?scenario)) = "economic growth") .

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0) .
}"}

