}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:category "Conservative" ;
       wm:investorName ?investorName .

  ?ph a wm:PortfolioHealth ;
       wm:healthOfInvestor ?inv ;
       wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50)

  ?hold a wm:PortfolioHolding ;
        wm:heldByInvestor ?inv ;
        wm:investmentName "Gold" .

  ?ra a wm:RebalancingAction ;
      wm:rebalancingActionOfInvestor ?inv ;
      wm:action "De-risking" .

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .
  ?inv wm:category "Conservative" .

  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:riskScore ?riskScore .
  FILTER(?riskScore > 50) .

  ?hold a wm:PortfolioHolding ;
        wm:heldByInvestor ?inv ;
        wm:investmentName "Gold" .

  ?reb a wm:RebalancingAction ;
       wm:rebalancingActionOfInvestor ?inv ;
       wm:action "Defensive Shift" .

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:shortfall ?shortfall .
  FILTER(?shortfall > 0) .
}"}

