{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?holdingId ?investmentName ?returnsPct ?cost ?currentValue
WHERE {
  ?holding a wm:PortfolioHolding .
  ?holding wm:holdingId ?holdingId .
  OPTIONAL { ?holding wm:investmentName ?investmentName . }
  OPTIONAL { ?holding wm:returnsPct ?returnsPct . }
  OPTIONAL { ?holding wm:cost ?cost . }
  OPTIONAL { ?holding wm:currentValue ?currentValue . }

  FILTER(bound(?returnsPct) && ?returnsPct < 0)
  FILTER(bound(?cost))
  FILTER(bound(?currentValue))
}"}

