{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?loss_holding_count
WHERE {
  # Investor with Aggressive risk tolerance
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "aggressive")

  # Portfolio health with riskScore > 75
  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 75)

  # Investment goal with shortfall > 0 (underfunded)
  ?goal a wm:InvestmentGoal ;
        wm:investorId ?investorId ;
        wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  # Banking sector allocation > 0%
  ?alloc a wm:SectorAllocation ;
         wm:investorId ?investorId ;
         wm:sector ?sector ;
         wm:allocationPct ?allocPct .
  FILTER(LCASE(STR(?sector)) = "banking")
  FILTER(xsd:decimal(?allocPct) > 0)

  # Count of loss‑making holdings (cost and currentValue present, currentValue < cost)
  {
    SELECT ?investorId (COUNT(?holdingId) AS ?loss_holding_count)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:holdingId ?holdingId ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(xsd:decimal(?currentValue) < xsd:decimal(?cost))
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?investorId ?investorName ?loss_holding_count"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?loss_holding_count WHERE {
  {
    SELECT ?investorId (COUNT(?holdingId) AS ?loss_holding_count) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:holdingId ?holdingId ;
               wm:cost ?cost ;
               wm:currentValue ?curr .
      FILTER(xsd:decimal(?cost) > xsd:decimal(?curr))
    } GROUP BY ?investorId
    HAVING (COUNT(?holdingId) > 0)
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category "Aggressive" ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?ph ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasSectorAllocation ?sa .
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 75)
  ?goal wm:progressPct ?prog .
  FILTER(xsd:decimal(?prog) < 100)
  ?sa wm:allocationPct ?allocPct ;
      wm:sector ?sector .
  FILTER(xsd:decimal(?allocPct) > 0)
  FILTER(LCASE(?sector) = "automobile")
}"}

