{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?scenario_shift_sum ?scenario_count
WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?raw_shift_sum) (COUNT(?scenarioRebalanceId) AS ?raw_count)
    WHERE {
      ?sr a wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?cur .
      ?sr wm:scenarioRebalanceId ?scenarioRebalanceId .
    }
    GROUP BY ?investorId
  }

  BIND(COALESCE(?raw_shift_sum, 0) AS ?scenario_shift_sum)
  BIND(COALESCE(?raw_count, 0) AS ?scenario_count)
}
ORDER BY ?investorId", "Q2": ""}

