{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?holdingId ?investmentName ?sector
WHERE {
  ?holding rdf:type wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:investmentName ?investmentName .
  OPTIONAL { ?holding wm:sector ?sectorLiteral . }
  OPTIONAL {
    ?holding wm:hasSector ?sectorEntity .
    ?sectorEntity rdfs:label ?sectorLabel .
  }
  BIND (COALESCE(?sectorLiteral, ?sectorLabel) AS ?sector)
  FILTER ( ?sector NOT IN ( "Automobile", "Banking", "Consumer Goods", "Corporate", "Financial Services", "Government", "Healthcare", "Infrastructure", "Pharma", "Private Equity", "Real Estate", "Technology" ) )
}"}

{"Q1": "PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
