SELECT ?investorId ?investorName ?riskTolerance
WHERE {
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
  OPTIONAL { ?inv wm:riskTolerance ?riskTolerance . }
  FILTER (!BOUND(?riskTolerance))
}"}

