{"Q1": "PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wm: <https://wealth.example.org/ontology/>

SELECT ?goalId ?currentValue ?investmentGoal ?timeToGoalMonths ?avgPostTaxReturnPct ?avgVolatilityPct ?shortfall ?targetAmount ?progressPct ?investorId ?description ?avgSharpeRatio ?belongsToInvestor ?sourceTable ?hasInvestmentGoalType ?stdDevAnnualReturnPct ?avgAnnualReturnPct
WHERE {
  ?ig rdf:type wm:InvestmentGoal .

  OPTIONAL { ?ig wm:goalId ?goalId . }
  OPTIONAL { ?ig wm:currentValue ?currentValue . }
  OPTIONAL { ?ig wm:investmentGoal ?investmentGoal . }
  OPTIONAL { ?ig wm:timeToGoalMonths ?timeToGoalMonths . }
  OPTIONAL { ?ig wm:avgPostTaxReturnPct ?avgPostTaxReturnPct . }
  OPTIONAL { ?ig wm:avgVolatilityPct ?avgVolatilityPct . }
  OPTIONAL { ?ig wm:shortfall ?shortfall . }
  OPTIONAL { ?ig wm:targetAmount ?targetAmount . }
  OPTIONAL { ?ig wm:progressPct ?progressPct . }
  OPTIONAL { ?ig wm:investorId ?investorId . }
  OPTIONAL { ?ig wm:description ?description . }
  OPTIONAL { ?ig wm:avgSharpeRatio ?avgSharpeRatio . }
  OPTIONAL { ?ig wm:belongsToInvestor ?belongsToInvestor . }
  OPTIONAL { ?ig wm:sourceTable ?sourceTable . }
  OPTIONAL { ?ig wm:hasInvestmentGoalType ?hasInvestmentGoalType . }
  OPTIONAL { ?ig wm:stdDevAnnualReturnPct ?stdDevAnnualReturnPct . }
  OPTIONAL { ?ig wm:avgAnnualReturnPct ?avgAnnualReturnPct . }

  FILTER (!BOUND(?shortfall))
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?cashFlowId ?investorId ?date ?amount ?type ?source ?sourceTable ?notes ?cashFlowOfInvestor ?hasCashFlowSource ?hasCashFlowType
WHERE {
