  OPTIONAL { ?cf wm:type ?type . }
  OPTIONAL { ?cf wm:source ?source . }
  OPTIONAL { ?cf wm:sourceTable ?sourceTable . }
  OPTIONAL { ?cf wm:notes ?notes . }
  OPTIONAL { ?cf wm:cashFlowOfInvestor ?cashFlowOfInvestor . }
  OPTIONAL { ?cf wm:hasCashFlowSource ?hasCashFlowSource . }
  OPTIONAL { ?cf wm:hasCashFlowType ?hasCashFlowType . }
  FILTER NOT EXISTS { ?cf wm:type ?any . }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?cashFlowId ?cashFlowOfInvestor ?amount ?hasCashFlowSource ?investorId ?date ?notes ?hasCashFlowType ?source ?sourceTable ?type
