{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?ra
       ?rebalancingActionOfInvestor
       ?amount
       ?logic
       ?investorId
       ?hasRebalancingLogic
       ?notes
       ?action
       ?hasRebalancingDecision
       ?targetAllocationPct
       ?sourceTable
       ?rebalanceId
       ?currentAllocationPct
WHERE {
  ?ra a wm:RebalancingAction .
  FILTER NOT EXISTS { ?ra wm:action ?action . }

  OPTIONAL { ?ra wm:rebalancingActionOfInvestor ?rebalancingActionOfInvestor . }
  OPTIONAL { ?ra wm:amount ?amount . }
  OPTIONAL { ?ra wm:logic ?logic . }
  OPTIONAL { ?ra wm:investorId ?investorId . }
  OPTIONAL { ?ra wm:hasRebalancingLogic ?hasRebalancingLogic . }
  OPTIONAL { ?ra wm:notes ?notes . }
  OPTIONAL { ?ra wm:action ?action . }   # will remain unbound due to filter
  OPTIONAL { ?ra wm:hasRebalancingDecision ?hasRebalancingDecision . }
  OPTIONAL { ?ra wm:targetAllocationPct ?targetAllocationPct . }
  OPTIONAL { ?ra wm:sourceTable ?sourceTable . }
  OPTIONAL { ?ra wm:rebalanceId ?rebalanceId . }
  OPTIONAL { ?ra wm:currentAllocationPct ?currentAllocationPct . }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?segment WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:segment ?seg . }
  BIND(COALESCE(STR(?seg), "NULL") AS ?segment)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?cashFlowId ?investorId ?amount ?date ?type
WHERE {
  ?cf rdf:type wm:CashFlow ;
      wm:cashFlowId ?cashFlowId ;
      wm:amount ?amount ;
      wm:date ?date ;
      wm:type ?type ;
      wm:cashFlowOfInvestor ?inv .
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:timeHorizon ?timeHorizon . }
  FILTER ( !BOUND(?timeHorizon) || ?timeHorizon NOT IN ("Long-term", "Medium-term", "Short-term") )
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId .
  FILTER NOT EXISTS {
    ?sr a wm:ScenarioRebalancing ;
        wm:investorId ?investorId .
  }
}"}

{"Q1": "SELECT COUNT(DISTINCT ig.investor_id) AS distinct_investor_count
FROM ATOM_ENTITY_INVESTMENT_GOAL_001 ig
WHERE NOT EXISTS (
    SELECT 1 FROM ATOM_EVENT_SCENARIO_REBALANCING_001 sr
    WHERE sr.investor_id = ig.investor_id
);"}

{"Q1": "SELECT COUNT(DISTINCT sa.investor_id) AS distinct_investor_count
FROM ATOM_ENTITY_SECTOR_ALLOCATION_001 AS sa
WHERE NOT EXISTS (
    SELECT 1 FROM ATOM_EVENT_SCENARIO_REBALANCING_001 AS sr
    WHERE sr.investor_id = sa.investor_id
);"}

{"Q1": "SELECT COUNT(DISTINCT ip.investor_id) AS investor_profile_without_rebalance_count
FROM ATOM_ENTITY_INVESTOR_PROFILE_001 ip
WHERE NOT EXISTS (
    SELECT 1 FROM ATOM_EVENT_REBALANCING_ACTION_001 ra
    WHERE ra.investor_id = ip.investor_id
);"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  # Investor must have a linked PortfolioHealth record
  FILTER EXISTS { ?investor wm:hasPortfolioHealth ?ph . }

  # Investor must NOT have any linked RebalancingAction record
  FILTER NOT EXISTS { ?investor wm:hasRebalancingAction ?ra . }
}
ORDER BY ?investorId"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  ?inv wm:hasPortfolioHealth ?ph .
  FILTER NOT EXISTS { ?inv wm:hasScenarioRebalancing ?sr . }
}
ORDER BY ?investorId"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv .
  }

  FILTER NOT EXISTS {
    ?ra a wm:RebalancingAction ;
        wm:rebalancingActionOfInvestor ?inv .
  }
}
ORDER BY ?investorId"}

{"Q1": "WITH sector_inv AS (
    SELECT DISTINCT investor_id
    FROM ATOM_ENTITY_SECTOR_ALLOCATION_001
),
scenario_inv AS (
    SELECT DISTINCT investor_id
    FROM ATOM_EVENT_SCENARIO_REBALANCING_001
)
SELECT COUNT(*) AS investor_count
FROM sector_inv si
WHERE NOT EXISTS (
    SELECT 1 FROM scenario_inv sc WHERE sc.investor_id = si.investor_id
);"}

{"Q1": "PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wm: <https://wealth.example.org/ontology/>

SELECT ?investmentGoal ?progressPct ?goalId
WHERE {
  ?ig rdf:type wm:InvestmentGoal .
  ?ig wm:progressPct ?progressPct .
  FILTER(?progressPct < 30) .
  ?ig wm:investmentGoal ?investmentGoal .
  ?ig wm:goalId ?goalId .
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName ?returnsPct ?cost ?currentValue
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:investmentName ?investmentName ;
           wm:returnsPct ?returnsPct ;
           wm:cost ?cost ;
           wm:currentValue ?currentValue .
  FILTER(xsd:decimal(?returnsPct) > 100)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskScore ?allocationPct
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?rt ;
       wm:hasPortfolioHealth ?ph ;
       wm:hasSectorAllocation ?sa .

  FILTER(LCASE(STR(?rt)) = "aggressive")

  ?ph wm:riskScore ?riskScore .
  FILTER(?riskScore > 75)

  ?sa wm:sector ?sector ;
      wm:allocationPct ?allocationPct .
  FILTER(LCASE(STR(?sector)) = "technology")
  FILTER(?allocationPct > 15)
}
ORDER BY ?investorId"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
WHERE {
  ?cf a wm:CashFlow .
  ?cf wm:amount ?amount .
  ?cf wm:date ?date .
  FILTER(?date >= "2022-01-01" && ?date <= "2022-12-31")
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
WHERE {
  ?cf a wm:CashFlow ;
      wm:amount ?amount ;
      wm:date ?date ;
      wm:cashFlowOfInvestor ?inv .
  ?inv wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "conservative")
  FILTER(xsd:date(?date) >= "2024-01-01"^^xsd:date && xsd:date(?date) <= "2024-12-31"^^xsd:date)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
WHERE {
  ?cf a wm:CashFlow ;
      wm:amount ?amount ;
      wm:date ?date ;
      wm:cashFlowOfInvestor ?inv .
  FILTER(?date >= "2025-01-01" && ?date <= "2025-12-31")
  ?inv a wm:Investor ;
       wm:segment ?seg .
  FILTER(LCASE(STR(?seg)) = "diversified")
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?net_cash_flow WHERE {
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:timeHorizon ?timeHorizon .
  FILTER(LCASE(STR(?timeHorizon)) = "short-term")

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?net_cash_flow) WHERE {
      ?cf rdf:type wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount ;
          wm:date ?date .
      FILTER(?date >= "2024-01-01"^^xsd:date && ?date <= "2024-12-31"^^xsd:date)
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?amount)) < 0)
  }
}"}

{"Q1": "PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?net_cash_flow WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(?riskTol) = "moderate")

  FILTER EXISTS {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:shortfall ?sf .
    FILTER(?sf > 0)
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?net_cash_flow) WHERE {
      ?cf a wm:CashFlow ;
           wm:investorId ?investorId ;
           wm:amount ?amt ;
           wm:date ?date .
      BIND(xsd:date(?date) AS ?dateTyped)
      FILTER(?dateTyped >= "2025-01-01"^^xsd:date && ?dateTyped <= "2025-12-31"^^xsd:date)
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amt)) < 0)
  }
}"}
